<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart3D — 3D Studio</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#202124;color:#ddd;font:12px Arial}.app{height:100vh;display:grid;grid-template-rows:44px 1fr 145px 28px}button{font:inherit;color:#ddd;background:#292b2f;border:1px solid #3d4045;border-radius:4px;cursor:pointer}button:hover{background:#35383d}.top{display:flex;align-items:center;gap:6px;padding:6px 9px;background:#18191c;border-bottom:1px solid #383a3f}.logo{font-weight:800;font-size:15px;margin:0 15px 0 5px}.logo b{color:#72adff}.top button{height:30px;min-width:30px}.main{min-height:0;display:grid;grid-template-columns:58px 1fr 235px}.rail{background:#1b1c20;border-right:1px solid #37393e;padding:7px 4px;display:flex;flex-direction:column;gap:6px;align-items:center}.rail button{width:46px;height:43px;font-size:18px}.rail small{display:block;font-size:8px;color:#999;margin-top:2px}.rail .active{background:#3b536d;border-color:#6595c2}.viewport{position:relative;min-width:0;background:#303236}.canvas{position:absolute;inset:0}.hint,.status{position:absolute;top:9px;background:#17181bcc;border:1px solid #494c51;border-radius:4px;padding:7px 9px;color:#aaa;pointer-events:none}.hint{left:9px}.status{right:9px}.right{background:#1e2024;border-left:1px solid #383a3f;overflow:auto}.tabs{display:flex;border-bottom:1px solid #383a3f}.tabs button{flex:1;border:0;border-radius:0;background:none;padding:10px;color:#999}.tabs .on{color:#fff;border-bottom:2px solid #72adff}.heading{padding:10px 11px 7px;text-transform:uppercase;letter-spacing:1px;font-weight:bold;color:#92969d;font-size:9px}.tree{padding:7px}.node{padding:8px;border-radius:4px;display:flex;gap:7px}.node.sel,.node:hover{background:#33363c}.muted{margin-left:auto;color:#777;font-size:10px}.inspector{padding:10px;border-top:1px solid #33363b}.field{margin:8px 0}.field label{display:block;color:#999;font-size:9px;margin-bottom:4px}.trip{display:grid;grid-template-columns:1fr 1fr 1fr;gap:5px}.field input{width:100%;height:27px;background:#121316;border:1px solid #3b3e43;border-radius:4px;color:#ddd;padding:0 5px}.timeline{display:grid;grid-template-columns:180px 1fr;background:#191b1e;border-top:1px solid #3b3d42}.tracks{border-right:1px solid #383a3f}.trackhead,.track{height:29px;padding:8px;border-bottom:1px solid #303238}.trackhead{color:#999}.sheet{overflow:hidden;position:relative;background:repeating-linear-gradient(90deg,#191b1e 0,#191b1e 39px,#27292e 40px)}.numbers{height:29px;display:flex;border-bottom:1px solid #303238;color:#777}.numbers span{width:40px;text-align:center;padding-top:8px}.playhead{position:absolute;left:12px;top:0;bottom:0;width:1px;background:#ef6570}.bottom{background:#18191c;border-top:1px solid #383a3f;display:flex;justify-content:space-between;align-items:center;padding:0 9px;color:#777;font-size:10px}@media(max-width:850px){.main{grid-template-columns:52px 1fr}.right{display:none}}
</style></head><body><div class="app"><header class="top"><div class="logo">SMART<b>3D</b></div><button id="new">＋</button><button id="undo">↶</button><button id="redo">↷</button><button id="save">▣</button><button id="play">▶</button><button id="export">EXPORT</button></header><div class="main"><aside class="rail"><button class="active" id="select">↖<small>Select</small></button><button id="move">✥<small>Move</small></button><button id="rotate">↻<small>Rotate</small></button><button id="scale">⤢<small>Scale</small></button><button id="addcube">■<small>Cube</small></button><button id="addlight">☀<small>Light</small></button><button id="addcamera">▣<small>Camera</small></button></aside><main class="viewport"><div id="canvas" class="canvas"></div><div class="hint">LMB select · drag orbit · wheel zoom · RMB pan</div><div id="status" class="status">Cube selected</div></main><aside class="right"><div class="tabs"><button class="on">Scene</button><button>Object</button></div><div class="heading">Scene</div><div class="tree" id="tree"></div><div class="inspector"><div class="heading" style="padding:0 0 7px">Transform</div><div id="inspector"></div></div></aside></div><div class="timeline"><div class="tracks"><div class="trackhead">TIMELINE</div><div class="track">Cube</div><div class="track">Camera</div><div class="track">Light</div></div><div class="sheet"><div class="numbers"><span>0</span><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span><span>60</span><span>70</span><span>80</span><span>90</span></div><div class="playhead" id="playhead"></div></div></div><footer class="bottom"><span>Smart3D</span><span id="mode">SELECT</span><span>Three.js WebGL</span></footer></div>
<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.180.0/examples/jsm/"}}</script><script type="module">
import * as THREE from 'three';import{OrbitControls}from'three/addons/controls/OrbitControls.js';import{TransformControls}from'three/addons/controls/TransformControls.js';
const host=document.getElementById('canvas'),scene=new THREE.Scene();scene.background=new THREE.Color(0x303236);const camera=new THREE.PerspectiveCamera(50,1,.1,1000);camera.position.set(7,5,8);const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;host.appendChild(renderer.domElement);const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.target.set(0,1,0);const tc=new TransformControls(camera,renderer.domElement);scene.add(tc.getHelper());tc.addEventListener('dragging-changed',e=>orbit.enabled=!e.value);scene.add(new THREE.GridHelper(20,20,0x59606a,0x3d4249));scene.add(new THREE.AmbientLight(0xffffff,.45));const light=new THREE.DirectionalLight(0xffffff,2.5);light.position.set(4,7,5);light.castShadow=true;light.name='Light';scene.add(light);const cube=new THREE.Mesh(new THREE.BoxGeometry(2,2,2),new THREE.MeshStandardMaterial({color:0x888888,roughness:.65}));cube.position.y=1;cube.castShadow=true;cube.name='Cube';scene.add(cube);const camHelper=new THREE.CameraHelper(camera);camHelper.name='Camera';camHelper.visible=false;scene.add(camHelper);let items=[cube,light,camHelper],selected=cube;function select(o){selected=o;tc.detach();if(o&&o.isMesh)tc.attach(o);document.getElementById('status').textContent=o.name+' selected';tree();inspector()}function tree(){document.getElementById('tree').innerHTML=items.map(o=>`<div class="node ${o===selected?'sel':''}" data-i="${items.indexOf(o)}">◈ ${o.name}<span class="muted">${o.type}</span></div>`).join('');document.querySelectorAll('.node').forEach(n=>n.onclick=()=>select(items[+n.dataset.i]))}function inspector(){const e=document.getElementById('inspector');e.innerHTML='<div class="trip">'+['x','y','z'].map(a=>`<div class="field"><label>Position ${a.toUpperCase()}</label><input data-p="${a}" value="${selected.position[a].toFixed(2)}"></div>`).join('')+'</div>';e.querySelectorAll('[data-p]').forEach(i=>i.oninput=()=>selected.position[i.dataset.p]=+i.value)}['select','move','rotate','scale'].forEach(id=>document.getElementById(id).onclick=()=>{document.getElementById('mode').textContent=id.toUpperCase();if(id==='select')tc.detach();else{tc.setMode({move:'translate',rotate:'rotate',scale:'scale'}[id]);if(selected.isMesh)tc.attach(selected)}});function add(t){let o;if(t==='cube'){o=new THREE.Mesh(new THREE.BoxGeometry(2,2,2),new THREE.MeshStandardMaterial({color:0x888888,roughness:.65}));o.position.set(0,1,0);o.name='Cube '+(items.filter(x=>x.name.startsWith('Cube')).length+1);o.castShadow=true}else if(t==='light'){o=new THREE.PointLight(0xffffff,4);o.position.set(3,4,2);o.name='Light '+(items.filter(x=>x.name.startsWith('Light')).length+1)}else{o=new THREE.PerspectiveCamera(50,1,.1,1000);o.position.set(4,3,5);o.name='Camera '+(items.filter(x=>x.name.startsWith('Camera')).length+1)}scene.add(o);items.push(o);select(o)}document.getElementById('addcube').onclick=()=>add('cube');document.getElementById('addlight').onclick=()=>add('light');document.getElementById('addcamera').onclick=()=>add('camera');document.getElementById('new').onclick=()=>{for(let i=items.length-1;i>0;i--){scene.remove(items[i]);items.pop()}cube.position.set(0,1,0);select(cube)};document.getElementById('save').onclick=()=>{const d={scene:'Smart3D',objects:items.map(o=>({name:o.name,type:o.type,position:o.position.toArray(),rotation:o.rotation.toArray()}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='smart3d-scene.json';a.click()};document.getElementById('play').onclick=()=>{let p=12;const h=document.getElementById('playhead');const t=setInterval(()=>{p+=2;h.style.left=p+'px';if(p>420){clearInterval(t);h.style.left='12px'}},100)};function resize(){const r=host.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height)}new ResizeObserver(resize).observe(host);resize();select(cube);(function loop(){requestAnimationFrame(loop);orbit.update();renderer.render(scene,camera)})();
</script></body></html>